mapper.select:
SELECT COUNT( t3.id ) AS cultivateNum, COUNT( DISTINCT t3.theme_id ) AS themeNum, sum( IF ( t3.exam_task_id IS NOT NULL, 1, 0 )) AS examNum, sum( IF ( t3.cultivate_mode = 'ONLINE', 1, 0 )) AS onlineNum, sum( IF ( t3.cultivate_mode = 'OFFLINE', 1, 0 )) AS offlineNum, sum( IF ( t3.cultivate_target = 'STAFF', 1, 0 )) AS staffNum, sum( IF ( t3.cultivate_target = 'MERCHANT', 1, 0 )) AS merchantNum FROM ( SELECT t.id, t.theme_id, t.exam_task_id, t.cultivate_mode, t.cultivate_target FROM cultivate_task t INNER JOIN cultivate_task_user t2 ON t.id = t2.cultivate_task_id WHERE t.deleted = 0
and t.cultivate_start_time >= #{period.begin} and t.cultivate_start_time < #{period.end}
GROUP BY t.id ) t3;

select t.theme_name as name,count(*) as num from cultivate_task t where t.deleted = 0
and t.cultivate_start_time >= #{period.begin} and t.cultivate_start_time < #{period.end}
group by t.theme_name

select t.cultivate_target as name,count(*) as num from cultivate_task t where t.deleted = 0
and t.cultivate_start_time >= #{period.begin} and t.cultivate_start_time < #{period.end}
group by t.cultivate_target

select DATE_FORMAT(t.cultivate_start_time,'%Y-%m') as name, count(*) as num from cultivate_task t where t.deleted = 0
and t.cultivate_start_time >= #{period.begin} and t.cultivate_start_time < #{period.end}
group by DATE_FORMAT(t.cultivate_start_time,'%Y-%m')

select t.id,t.code,t.name,t.theme_id,t.theme_name,t.cultivate_start_time,t.cultivate_end_time, t.exam_task_id,cultivate_user_number,cultivate_mode,t.cultivate_target,t.cultivate_address, t.speaker,t.charge_user_id,t.charge_user_name,t.cultivate_content,t.cultivate_task_status, t.tenant,u.user_id,u.user_name,u.user_phone,u.user_sign_status,u.user_sign_time,u.belated, u.merchant_id,u.merchant_name from cultivate_task_user u inner join cultivate_task t on u.cultivate_task_id = t.id where t.deleted = 0 and t.cultivate_task_status != 'WAIT_PUBLISH'
and u.user_id = #{param.userId}
and t.name like concat('%',#{param.keyword},'%')
and t.cultivate_task_status = #{param.cultivateTaskStatus}
order by t.create_time desc

SELECT t.id, t.CODE, t.NAME, t.theme_id, t.theme_name, t.source_code, t.cultivate_start_time, t.cultivate_end_time, t.exam_task_id, cultivate_user_number, cultivate_mode, t.cultivate_target, t.cultivate_address, t.speaker, t.charge_user_id, t.charge_user_name, t.cultivate_content, t.cultivate_task_status, t.tenant, t.user_id, t.user_name, t.user_phone, t.user_sign_status, t.user_sign_time, t.belated, t.merchant_id, t.merchant_name FROM ( SELECT t.id, t.CODE, t.NAME, t.theme_id, t.theme_name, t.source_code, t.cultivate_start_time, t.cultivate_end_time, t.exam_task_id, cultivate_user_number, cultivate_mode, t.cultivate_target, t.cultivate_address, t.speaker, t.charge_user_id, t.charge_user_name, t.cultivate_content, t.cultivate_task_status, t.tenant, NULL AS user_id, NULL AS user_name, NULL AS user_phone, NULL AS user_sign_status, NULL AS user_sign_time, NULL AS belated, NULL AS merchant_id, NULL AS merchant_name, t.create_time FROM cultivate_task t WHERE t.deleted = 0 AND t.cultivate_task_status != 'WAIT_PUBLISH' AND ( SELECT COUNT( 1 ) FROM cultivate_task_user WHERE cultivate_task_id = t.id AND user_identify = #{param.userIdentify} ) <= 0
and t.name like concat('%',#{param.keyword},'%')
and t.market_tenant = #{param.marketTenant}
and t.cultivate_task_status = #{param.cultivateTaskStatus}
GROUP BY t.id UNION SELECT t.id, t.CODE, t.NAME, t.theme_id, t.theme_name, t.source_code, t.cultivate_start_time, t.cultivate_end_time, t.exam_task_id, cultivate_user_number, cultivate_mode, t.cultivate_target, t.cultivate_address, t.speaker, t.charge_user_id, t.charge_user_name, t.cultivate_content, t.cultivate_task_status, t.tenant, u.user_id, u.user_name, u.user_phone, u.user_sign_status, u.user_sign_time, u.belated, u.merchant_id, u.merchant_name, t.create_time FROM cultivate_task t INNER JOIN cultivate_task_user u ON u.cultivate_task_id = t.id AND u.deleted = 0 WHERE t.deleted = 0 AND t.cultivate_task_status != 'WAIT_PUBLISH' AND u.user_identify = #{param.userIdentify}
and t.market_tenant = #{param.marketTenant}
and t.name like concat('%',#{param.keyword},'%')
and t.cultivate_task_status = #{param.cultivateTaskStatus}
GROUP BY t.id ) t order by t.create_time desc

select id, code, `name`, theme_id, theme_name, source_code, source_name, source_key, cultivate_start_time, cultivate_end_time, exam_task_id, cultivate_user_number, cultivate_mode, cultivate_target, cultivate_address, speaker, charge_user_id, charge_user_name, cultivate_content, cultivate_task_status, tenant, deleted, create_by, creator_id, creator_type, create_time, update_by, update_time from cultivate_task
tenant = #{tenant}
and `name` like concat('%',#{param.keyword},'%')
and cultivate_task_status = #{param.cultivateTaskStatus}
and update_time >= #{param.period.begin} and update_time < #{param.period.end}

select t.theme_id as id, t.theme_name as `name`, count(*) as total_num from cultivate_task t
and t.cultivate_start_time >= #{query.period.begin} and t.cultivate_start_time < #{query.period.end}
group by t.theme_id,t.theme_name

SELECT
COUNT( DISTINCT ctu.user_identify )
FROM
cultivate_task_user ctu


        and ctu.create_time >= #{query.period.begin}


        and ctu.create_time <= #{query.period.end}
